/**
 * The ToonTalk "room" chrome — a reconstruction of the original desktop scene:
 * a tan LEGO-baseplate floor, the open toolbox (top-right) whose icons can be
 * picked to drop a fresh element on the floor, an open notebook (bottom), the
 * wand and vacuum tools (left), and the giant hand cursor on a red arm that
 * follows the pointer.
 *
 * Presentation only: it draws onto the renderer's background (below the
 * interactive things) plus a top cursor layer. It reads textures and emits
 * pick events; it never touches the model directly.
 */
import * as PIXI from 'pixi.js';
import { assetUrl } from '../config/asset-url';
import type { Renderer } from './renderer';
import type { RenderTheme } from '../config/render-mode';
import type { Thing } from '../model/thing';
import { NumberThing } from '../model/number';
import { TextThing } from '../model/text';
import { Box } from '../model/box';
import { Nest } from '../model/nest';
import { Scale } from '../model/scale';
import { Robot } from '../model/robot';
import { Truck } from '../model/truck';
import { Bomb } from '../model/bomb';
import { renderThingDisplay } from './display';
import { addModeButton } from './lego-button';

const ROOM_KEYS = ['floor', 'toolbox', 'toolbox-open', 'notebook', 'hand', 'hand-point', 'hand-grab', 'hand-wand', 'truck', 'thought-bubble'] as const;

export async function loadRoomTextures(theme: RenderTheme): Promise<Map<string, PIXI.Texture>> {
  const scaleMode =
    theme.scaleMode === 'nearest' ? PIXI.SCALE_MODES.NEAREST : PIXI.SCALE_MODES.LINEAR;
  const map = new Map<string, PIXI.Texture>();
  await Promise.all(
    ROOM_KEYS.map(async (key) => {
      try {
        const tex = await PIXI.Assets.load(assetUrl(`/assets/room/${key}.png`));
        tex.baseTexture.scaleMode = scaleMode;
        map.set(key, tex);
      } catch {
        map.set(key, PIXI.Texture.WHITE);
      }
    }),
  );
  // Per-house-style floor baseplates (a=tan, b=blue, c=green) so the working
  // floor matches the house you entered (city-baked FLOOR arts).
  await Promise.all(
    (['a', 'b', 'c'] as const).map(async (s) => {
      try {
        const tex = await PIXI.Assets.load(assetUrl(`/assets/city/floor-${s}.png`));
        tex.baseTexture.scaleMode = scaleMode;
        map.set(`floor-${s}`, tex);
      } catch {
        /* fall back to the default tan floor */
      }
    }),
  );
  return map;
}

/** Called when a toolbox/tool icon is clicked; spawns that element in the world. */
/** Take a fresh copy of a toolbox element out at (x, y) — an infinite stack. */
export type PickHandler = (key: string, x: number, y: number) => void;

const ARM_COLOR = 0xb1584f; // brick red, sampled from the hand texture's red wrist stub

/** Blend two 0xRRGGBB colours (t: 0→a, 1→b) — used to tint a tool from clay to
 * its Lego look as it rises during the sit-down sequence. */
function lerpColor(a: number, b: number, t: number): number {
  const ar = (a >> 16) & 255, ag = (a >> 8) & 255, ab = a & 255;
  const br = (b >> 16) & 255, bg = (b >> 8) & 255, bb = b & 255;
  return (
    (Math.round(ar + (br - ar) * t) << 16) |
    (Math.round(ag + (bg - ag) * t) << 8) |
    Math.round(ab + (bb - ab) * t)
  );
}

/**
 * Per-pose cursor calibration. Each hand frame has its hotspot (anchor) and a
 * red wrist stub the sleeve must continue — stub centre offset (`cx`, fraction
 * of width from centre), width (`w`), and where it starts down the sprite
 * (`top`), all measured from the bitmaps.
 */
type HandPose = 'open' | 'grab' | 'holdwand';
interface PoseSpec {
  key: string;
  anchor: [number, number];
  scale: number;
  cx: number;
  w: number;
  top: number;
}
const HAND_POSES: Record<HandPose, PoseSpec> = {
  // Empty: the POINTING hand (HAND04) — index extended, others curled, like the
  // original's idle cursor. Hotspot at the fingertip (top); red wrist stub at the
  // bottom-centre.
  open: { key: 'hand-point', anchor: [0.54, 0.02], scale: 0.47, cx: 0.17, w: 0.33, top: 0.86 },
  grab: { key: 'hand-grab', anchor: [0.5, 0.2], scale: 1.2, cx: 0.26, w: 0.36, top: 0.69 },
  // Holding the wand: the hand grips it on the right, tip points left (hotspot);
  // wrist is far right (~0.83w). Wide sprite, so scaled down. (May need tuning.)
  holdwand: { key: 'hand-wand', anchor: [0.06, 0.42], scale: 0.85, cx: 0.77, w: 0.33, top: 0.16 },
};

export class Room {
  private readonly floor: PIXI.TilingSprite;
  private readonly chrome: PIXI.Container;
  private readonly cursor: PIXI.Container;
  private readonly handSprite: PIXI.Sprite;
  private readonly arm: PIXI.Graphics;
  /** Tooly can be picked up and moved: drag state for the open-toolbox image. */
  private tbBox?: PIXI.Container;
  private tbDragging = false;
  private tbOff = { x: 0, y: 0 };
  private tbWired = false;
  /** The full-screen mist while inside a robot's thoughts (training), or none. */
  private thoughtMist?: PIXI.Container;
  /** The Tooly compartment/chip icon under the pointer — it wiggles to show it's
   * ready to be picked up (like a selected thing on the floor). */
  private toolHover: { node: PIXI.Container; x: number; y: number } | null = null;
  /** The open Tooly tray + the spilled tool chips, captured during layout so the
   * sit-down sequence can pop Tooly open and rise the tools out of it. */
  private toolboxContainer: PIXI.Container | null = null;
  private toolChips: Array<{ node: PIXI.Container; tx: number; ty: number; tilt: number }> = [];

  constructor(
    private readonly renderer: Renderer,
    private readonly room: Map<string, PIXI.Texture>,
    private readonly tools: Map<string, PIXI.Texture>,
    private readonly theme: RenderTheme,
    private readonly onPick: PickHandler,
    /** True if a real tool of this kind is already OUT in the world — then its
     * spilled chip is hidden, so there's never a chip AND a held/floor copy. */
    private readonly toolExists?: (kind: string) => boolean,
  ) {
    this.floor = new PIXI.TilingSprite(
      room.get('floor') ?? PIXI.Texture.WHITE,
      renderer.width,
      renderer.height,
    );
    renderer.background.addChild(this.floor);

    this.chrome = new PIXI.Container();
    renderer.background.addChild(this.chrome);
    this.layoutChrome();

    this.cursor = new PIXI.Container();
    this.cursor.eventMode = 'none';
    this.arm = new PIXI.Graphics();
    this.handSprite = new PIXI.Sprite();
    this.cursor.addChild(this.arm, this.handSprite);
    renderer.app.stage.addChild(this.cursor);
    this.applyPose('open');
    this.setHand(renderer.width * 0.45, renderer.height * 0.45);
    renderer.app.ticker.add(this.tickToolWiggle);

    // (Cursor pose is driven by the drag controller via setPose, based on what
    // the hand is holding.)

    // Keep the floor + chrome covering the whole canvas on any renderer resize
    // (fires on the initial auto-resize too, so the floor always fills the tab).
    renderer.app.renderer.on('resize', () => this.resize());
  }

  private pose: HandPose = 'open';
  private handX = 0;
  private handY = 0;
  /** Tooly starts closed (the green box-creature); click opens the tray. */
  private toolboxOpen = true;

  private applyPose(pose: HandPose): void {
    this.pose = pose;
    const spec = HAND_POSES[pose];
    this.handSprite.texture = this.room.get(spec.key) ?? PIXI.Texture.WHITE;
    this.handSprite.anchor.set(spec.anchor[0], spec.anchor[1]);
    this.handSprite.scale.set(spec.scale);
  }

  setPose(pose: HandPose): void {
    if (pose === this.pose) return;
    this.applyPose(pose);
    this.setHand(this.handX, this.handY);
  }

  /** While a tool (Pumpy/Dusty) is held, drop the hand cursor BEHIND the things
   * layer so the held tool — which lives there, on top — shows in front of the
   * hand (you should see most of the tool, not the hand covering it). The hand
   * grips it from behind. Restored on top otherwise. */
  setCursorBehind(behind: boolean): void {
    const stage = this.renderer.app.stage;
    const tlIndex = stage.getChildIndex(this.renderer.thingLayer);
    stage.setChildIndex(this.cursor, behind ? tlIndex : stage.children.length - 1);
  }

  resize(): void {
    this.floor.width = this.renderer.width;
    this.floor.height = this.renderer.height;
    this.chrome.removeChildren().forEach((c) => c.destroy({ children: true }));
    this.layoutChrome();
  }

  /** Set the floor baseplate to the entered house's style (a=tan, b=blue,
   * c=green) so the working floor matches the house outside. */
  setFloorStyle(style: 'a' | 'b' | 'c'): void {
    const tex = this.room.get(`floor-${style}`) ?? this.room.get('floor');
    if (tex) this.floor.texture = tex;
  }

  /** Scroll the floor baseplate to match the floor camera (the toolbox chrome
   * stays put), so the studs slide as you sit at different spots. */
  setFloorPan(camX: number, camY: number): void {
    this.floor.tilePosition.set(-camX, -camY);
  }

  /** Show/hide the whole room (floor, chrome, hand cursor) — used when the
   * city scene is on top. Presentation only. */
  setVisible(v: boolean): void {
    this.floor.visible = v;
    this.chrome.visible = v;
    this.cursor.visible = v;
  }

  /** Hide just the hand cursor — inside a robot's thoughts you control the robot
   * (it's the cursor), so the hand should not appear. */
  setHandHidden(hidden: boolean): void {
    this.cursor.visible = !hidden;
  }

  /**
   * Enter the robot's thoughts (robot.htm: "drop a box on him… you enter into
   * the robot's thoughts and control him"). Lays a full-screen misty cloud over
   * the floor — between the floor and the toolbox chrome, so Tooly stays usable
   * inside the thoughts — replacing the room with the soft thought-bubble
   * interior. The box + robot live in the thingLayer above it (main hides the
   * other floor things). Idempotent.
   */
  enterThoughtBubble(): void {
    if (this.thoughtMist) return;
    const mist = this.makeMist(this.renderer.width, this.renderer.height);
    mist.eventMode = 'none';
    // index 1 = above the floor (0), below the chrome — so Tooly AND the spilled
    // tools (wand/Dusty/Pumpy) stay available inside the thoughts.
    this.renderer.background.addChildAt(mist, 1);
    this.thoughtMist = mist;
  }

  /** Leave the robot's thoughts — remove the mist, the floor returns. */
  exitThoughtBubble(): void {
    if (this.thoughtMist) {
      if (!this.thoughtMist.destroyed) this.thoughtMist.destroy({ children: true });
      this.thoughtMist = undefined;
    }
  }

  get inThoughtBubble(): boolean {
    return this.thoughtMist != null;
  }

  /** The thought-bubble interior filling (w,h) — the real BIGBUBBL cloud
   * (cover-scaled), or a soft procedural mist if the art is missing. */
  private makeMist(w: number, h: number): PIXI.Container {
    const c = new PIXI.Container();
    const tex = this.room.get('thought-bubble');
    if (tex && tex !== PIXI.Texture.WHITE) {
      const s = new PIXI.Sprite(tex);
      const cover = Math.max(w / tex.width, h / tex.height);
      s.scale.set(cover);
      s.anchor.set(0.5);
      s.position.set(w / 2, h / 2); // centre-cover the viewport
      c.addChild(s);
      return c;
    }
    const g = new PIXI.Graphics();
    g.beginFill(0xeef0f6, 1);
    g.drawRect(0, 0, w, h);
    g.endFill();
    for (let i = 0; i < 22; i++) {
      const light = i % 3 !== 0;
      g.beginFill(light ? 0xffffff : 0xd9dbe6, light ? 0.45 : 0.4);
      g.drawEllipse((i * 137.5) % w, (i * 89.3) % h, 120 + ((i * 53) % 140), 90 + ((i * 37) % 110));
      g.endFill();
    }
    c.addChild(g);
    return c;
  }

  /** Move the hand so its fingertip points at (x, y); the sleeve continues the
   * hand texture's wrist stub (same colour, position and width) down off-screen. */
  setHand(x: number, y: number): void {
    this.handX = x;
    this.handY = y;
    this.handSprite.position.set(x, y);
    const spec = HAND_POSES[this.pose];
    const w = this.handSprite.width;
    const h = this.handSprite.height;
    const armCx = x + w * spec.cx;
    const armW = w * spec.w;
    const wristY = y + h * spec.top; // starts inside the hand, emerges at the wrist
    const bottom = this.renderer.height + 40;
    this.arm.clear();
    this.arm.beginFill(ARM_COLOR, 1);
    this.arm.drawRoundedRect(armCx - armW / 2, wristY, armW, bottom - wristY, armW * 0.5);
    this.arm.endFill();
  }

  // --- chrome layout -------------------------------------------------------

  private layoutChrome(): void {
    const W = this.renderer.width;
    const H = this.renderer.height;

    // Tooly the toolbox lives at hand (top-right, screen-fixed so it "follows"
    // you). Closed it's the green box-creature; click it to OPEN the tray with
    // the tool stacks + the hand tools (faithful to the original — Video 8). The
    // tools stay inside Tooly (hidden) until it's open.
    if (!this.toolboxOpen) {
      const tooly = this.makeToolyClosed();
      tooly.position.set(W - 130, 150);
      this.chrome.addChild(tooly);
      return;
    }

    const toolbox = this.makeToolbox();
    toolbox.position.set(W - 270, 255); // bigger Tooly — keep it clear of the screen edge
    this.chrome.addChild(toolbox);
    this.toolboxContainer = toolbox;
    this.toolChips = [];

    // Opening Tooly SPILLS the hand tools out onto the floor below it (the wand,
    // Dusty the vacuum, Pumpy the pump), as in the original — each is its own
    // sprite at a tilt; picking one pulls a fresh copy out at the cursor.
    // Full-size, so spread them across the open floor (Tooly is top-right, the
    // notebook bottom-centre) rather than the old tight miniature cluster.
    const spill: Array<[string, string, number, number, number]> = [
      ['dusty', 'S', W * 0.2, H * 0.44, 0.08],
      ['pumpy', '+', W * 0.43, H * 0.56, 0.15],
      ['wand', 'C', W * 0.24, H * 0.72, -0.15],
    ];
    for (const [pick, badge, x, y, tilt] of spill) {
      if (this.toolExists?.(pick)) continue; // that tool is already out — no chip copy
      const chip = this.makeToolChip(pick, badge, tilt);
      chip.position.set(x, y);
      this.wireToolHover(chip, chip, x, y); // a spilled tool wiggles when hovered too
      this.chrome.addChild(chip);
      this.toolChips.push({ node: chip, tx: x, ty: y, tilt });
    }
    // The `claude 1` main notebook is the real interactive World object (filed
    // pages persist), so it's not chrome.
  }

  /** Open/close Tooly (rebuild the chrome). */
  private toggleToolbox(): void {
    this.toolboxOpen = !this.toolboxOpen;
    this.chrome.removeChildren().forEach((c) => c.destroy({ children: true }));
    this.layoutChrome();
  }

  /** Rebuild the chrome in place (keeps open/closed state) — call when a tool is
   * taken out or removed so its spilled chip disappears/reappears. */
  relayout(): void {
    this.chrome.removeChildren().forEach((c) => c.destroy({ children: true }));
    this.layoutChrome();
  }

  /** The sit-down sequence (called on entering the floor): Tooly pops open and
   * the tools rise out of it, growing into place and tinting from clay to their
   * Lego colour. */
  playSitDown(): void {
    if (!this.toolboxOpen || !this.toolboxContainer) return;
    const ox = this.toolboxContainer.position.x;
    const oy = this.toolboxContainer.position.y;
    this.popOpen(this.toolboxContainer, 680);
    // Tooly morphs clay → Lego: its closed clay form briefly overlays the open
    // tray and fades, revealing the Lego tray growing underneath.
    const clay = this.makeToolyClosed();
    clay.position.set(ox, oy);
    const trayW = this.toolboxContainer.width || 200;
    if (clay.width > 0) clay.scale.set((trayW * 0.95) / clay.width);
    this.chrome.addChild(clay);
    this.fadeOutAndRemove(clay, 820);
    this.toolChips.forEach((c, i) => this.riseTool(c, ox, oy, 300 + i * 340));
  }

  /** Fade a node to transparent over `ms`, then remove it. */
  private fadeOutAndRemove(node: PIXI.Container, ms: number): void {
    const t0 = performance.now();
    const tick = (): void => {
      if (node.destroyed) { this.renderer.app.ticker.remove(tick); return; }
      const t = Math.min(1, (performance.now() - t0) / ms);
      node.alpha = 1 - t;
      if (t >= 1) { this.renderer.app.ticker.remove(tick); node.destroy({ children: true }); }
    };
    this.renderer.app.ticker.add(tick);
  }

  /** Tooly "opens": a quick ease-out scale pop from small to full. */
  private popOpen(node: PIXI.Container, ms: number): void {
    const t0 = performance.now();
    node.scale.set(0.55);
    const tick = (): void => {
      if (node.destroyed) { this.renderer.app.ticker.remove(tick); return; }
      const t = Math.min(1, (performance.now() - t0) / ms);
      node.scale.set(0.55 + 0.45 * (1 - Math.pow(1 - t, 3)));
      if (t >= 1) this.renderer.app.ticker.remove(tick);
    };
    this.renderer.app.ticker.add(tick);
  }

  /** A tool rises out of Tooly (from ox,oy), grows into place, and tints from a
   * warm clay colour to none (its Lego look) as it settles. */
  private riseTool(c: { node: PIXI.Container; tx: number; ty: number; tilt: number }, ox: number, oy: number, delay: number): void {
    const { node, tx, ty, tilt } = c;
    const body = node.children[0] as PIXI.Sprite | undefined;
    const ms = 820;
    const start = performance.now() + delay;
    node.visible = false; // stays hidden inside Tooly until its turn
    const tick = (): void => {
      if (node.destroyed) { this.renderer.app.ticker.remove(tick); return; }
      const now = performance.now();
      if (now < start) return;
      node.visible = true;
      const t = Math.min(1, (now - start) / ms);
      const e = 1 - Math.pow(1 - t, 3); // ease-out
      node.position.set(ox + (tx - ox) * e, oy + (ty - oy) * e);
      node.scale.set(0.2 + 0.8 * e);
      node.rotation = tilt * e;
      if (body && body.tint !== undefined) body.tint = e >= 1 ? 0xffffff : lerpColor(0xd79a6a, 0xffffff, e);
      if (t >= 1) this.renderer.app.ticker.remove(tick);
    };
    this.renderer.app.ticker.add(tick);
  }

  /** Closed Tooly — the real claymation toolbox (toolbox.png from M22): a
   * blue-grey lego box with a red handle and little feet. Click to open. */
  private makeToolyClosed(): PIXI.Container {
    const c = new PIXI.Container();
    const tex = this.room.get('toolbox');
    if (tex && tex !== PIXI.Texture.WHITE) {
      const s = new PIXI.Sprite(tex);
      s.anchor.set(0.5);
      s.scale.set(160 / Math.max(s.width, 1)); // display ~160px wide
      c.addChild(s);
      c.hitArea = new PIXI.Rectangle(-s.width / 2, -s.height / 2, s.width, s.height);
    } else {
      const g = new PIXI.Graphics(); // fallback if the bitmap is missing
      g.beginFill(0x6b8aa0, 1);
      g.drawRoundedRect(-66, -40, 132, 92, 14);
      g.endFill();
      g.beginFill(0xc23b34, 1);
      g.drawRoundedRect(-30, -52, 60, 14, 7);
      g.endFill();
      c.addChild(g);
      c.hitArea = new PIXI.Rectangle(-66, -54, 132, 110);
    }
    c.eventMode = 'static';
    c.cursor = 'pointer';
    c.on('pointerdown', () => this.toggleToolbox());
    return c;
  }

  /** A toolbox hand-tool chip (chrome): the tool's icon + a small mode badge;
   * clicking pulls a fresh copy out at the cursor. */
  /** A hand tool spilled onto the floor by the open Tooly — just the tool's own
   * sprite (no background), big enough to read, with a small mode badge; clicking
   * pulls a fresh copy into the hand. */
  private makeToolChip(pick: string, badge: string, tilt = 0): PIXI.Container {
    const c = new PIXI.Container();
    // The spilled tool is its FULL-SIZE Lego sprite (the same thing you get when
    // you pull it out), not a miniature.
    const tex = this.tools.get(pick);
    let w = 96;
    let h = 96;
    if (tex && tex !== PIXI.Texture.WHITE) {
      const s = new PIXI.Sprite(tex);
      s.anchor.set(0.5);
      c.addChild(s);
      w = s.width;
      h = s.height;
    }
    // Mode shown as a 1×1 Lego plate on the tool (per-tool spot).
    addModeButton(c, badge, this.theme, pick, w, h, this.tools);
    c.rotation = tilt;
    c.hitArea = new PIXI.Rectangle(-w / 2, -h / 2, w, h);
    c.eventMode = 'static';
    c.cursor = 'grab';
    // Handle the pick here and stop it bubbling to the stage, so the tool is put
    // straight into the hand (via onPick) rather than the stage also reacting.
    c.on('pointerdown', (e) => {
      e.stopPropagation();
      this.onPick(pick, e.global.x, e.global.y);
    });
    return c;
  }

  /** A studded lego panel (the toolbox lid). Tinted to Tooly's green by default. */
  private studdedPanel(
    w: number,
    h: number,
    base = 0x8d8896,
    studLight = 0xa7a2b0,
    studDark = 0x6a6675,
  ): PIXI.Container {
    const c = new PIXI.Container();
    const g = new PIXI.Graphics();
    g.lineStyle(2, studDark, 1);
    g.beginFill(base, 1);
    g.drawRoundedRect(-w / 2, -h / 2, w, h, 6);
    g.endFill();
    const step = 18;
    g.lineStyle(0);
    for (let sx = -w / 2 + step; sx < w / 2 - 4; sx += step) {
      for (let sy = -h / 2 + step; sy < h / 2 - 4; sy += step) {
        g.beginFill(studLight, 1);
        g.drawCircle(sx, sy, 4);
        g.endFill();
        g.beginFill(studDark, 0.6);
        g.drawCircle(sx + 1, sy + 2, 4);
        g.endFill();
      }
    }
    c.addChild(g);
    return c;
  }

  /** Tooly open: the real cropped photo of the original toolbox if we have it,
   * else the drawn grey-lego reconstruction. */
  private makeToolbox(): PIXI.Container {
    const tex = this.room.get('toolbox-open');
    if (tex && tex !== PIXI.Texture.WHITE) return this.makeToolboxImage(tex);
    return this.makeToolboxDrawn();
  }

  /** The open toolbox as the original high-res artwork (NPICS TBMRPH09 PICT +
   * mask → clean alpha) with the real element icons rendered into the tray and a
   * hit area over each that picks that element. */
  private makeToolboxImage(tex: PIXI.Texture): PIXI.Container {
    const box = new PIXI.Container();
    this.tbBox = box;
    const sprite = new PIXI.Sprite(tex);
    sprite.anchor.set(0.5);
    sprite.scale.set(500 / Math.max(sprite.width, 1)); // ~500px wide (bigger Tooly so items fit)
    box.addChild(sprite);
    const W = sprite.width;
    const H = sprite.height;

    // Tooly can be picked up: grabbing the toolbox body (not a compartment)
    // drags the whole thing. Compartment hit areas sit on top and stopPropagation.
    sprite.eventMode = 'static';
    sprite.cursor = 'grab';
    sprite.on('pointerdown', (e) => {
      e.stopPropagation();
      this.tbDragging = true;
      this.tbOff = { x: box.position.x - e.global.x, y: box.position.y - e.global.y };
    });
    if (!this.tbWired) {
      this.tbWired = true;
      const stage = this.renderer.app.stage;
      stage.on('pointermove', (e) => {
        if (this.tbDragging && this.tbBox && !this.tbBox.destroyed) {
          this.tbBox.position.set(e.global.x + this.tbOff.x, e.global.y + this.tbOff.y);
        }
      });
      const stop = (): void => { this.tbDragging = false; };
      stage.on('pointerup', stop);
      stage.on('pointerupoutside', stop);
    }
    // The open tray (tbmrph16) holds eight compartments in a 2×4 grid on the
    // LEFT (the lid is folded back on the right). Per tools.cpp
    // compartment_contents, the contents run row-major (index = row*2 + col):
    // number,text / box,nest / scale,robot / truck,bomb. Compartment centres are
    // measured on the trimmed art; the grid tilts slightly (right column higher),
    // so each column gets its own row baselines.
    const colX = [0.205, 0.408];
    const rowY = [
      [0.345, 0.487, 0.628, 0.765], // left column (col 0)
      [0.315, 0.457, 0.598, 0.735], // right column (col 1), tilted up a touch
    ];
    const slots: Array<[string, number, number]> = [ // [pick, col, row]
      ['number', 0, 0], ['text', 1, 0],
      ['box', 0, 1], ['nest', 1, 1],
      ['scale', 0, 2], ['robot', 1, 2],
      ['truck', 0, 3], ['bomb', 1, 3],
    ];
    // Each item is fit INSIDE its compartment box (wider than tall), so a tall
    // plate and a wide truck both sit cleanly without overflow (cf. the original's
    // TO_FIT_INSIDE cw×ch, cw=W/8, ch=H/10).
    const cellW = W * 0.195;
    const cellH = H * 0.138;
    for (const [pick, col, row] of slots) {
      const cx = (colX[col] - 0.5) * W;
      const cy = (rowY[col][row] - 0.5) * H;
      const sample = this.sampleThing(pick);
      let icon: PIXI.Container | null = null;
      if (sample) {
        // static: the robot stays a still Lego figure in Tooly until taken out.
        // stretch: reshaped to fill its compartment (taken out → natural size).
        // Fit each element INSIDE its compartment preserving aspect (not stretched
        // to fill — that distorts the plates/studs). Scaled up so it fills the cell
        // on its limiting dimension, like the original's tray icons.
        icon = renderThingDisplay(sample, this.tools, this.theme, cellW, {
          static: true,
          maxHeight: cellH,
          scaleUp: true,
        });
        icon.position.set(cx, cy);
        box.addChild(icon);
      }
      const hit = new PIXI.Container();
      hit.position.set(cx, cy);
      hit.hitArea = new PIXI.Rectangle(-cellW / 2, -cellH / 2, cellW, cellH);
      hit.eventMode = 'static';
      hit.cursor = 'grab';
      // Handle here and don't bubble, so the pick "births" the element rather
      // than the stage dragging the toolbox.
      hit.on('pointerdown', (e) => {
        e.stopPropagation();
        this.onPick(pick, e.global.x, e.global.y);
      });
      if (icon) this.wireToolHover(hit, icon, cx, cy); // wiggle it while hovered
      box.addChild(hit);
    }
    return box;
  }

  /** While the pointer is over a Tooly compartment/chip, its icon wiggles —
   * "this is ready to be picked up" — and settles when the pointer leaves. */
  private wireToolHover(hit: PIXI.Container, icon: PIXI.Container, x: number, y: number): void {
    hit.on('pointerover', () => {
      this.toolHover = { node: icon, x, y };
    });
    hit.on('pointerout', () => {
      if (this.toolHover?.node === icon) {
        icon.position.set(x, y);
        this.toolHover = null;
      }
    });
  }

  /** The 2px circular selection wiggle (sprite.cpp selection_delta), applied to
   * the hovered Tooly icon. */
  private tickToolWiggle = (): void => {
    const t = this.toolHover;
    if (!t || t.node.destroyed) return;
    const D = 2;
    const phase = Math.floor((performance.now() % 400) / 100);
    const dx = phase === 0 ? D : phase === 2 ? -D : 0;
    const dy = phase === 1 ? D : phase === 3 ? -D : 0;
    t.node.position.set(t.x + dx, t.y + dy);
  };

  private makeToolboxDrawn(): PIXI.Container {
    const box = new PIXI.Container();
    const cols = 2;
    const rows = 4;
    const cell = 56;
    const gap = 10;
    const pad = 16;
    const w = cols * cell + (cols - 1) * gap + pad * 2;
    const h = rows * cell + (rows - 1) * gap + pad * 2;
    const depth = 16; // how tall the tray's 3-D front/side walls read

    // Open lid: a studded lego panel hinged up to the right, tilted back so we
    // see it edge-on (foreshortened), with hinge knobs joining it to the tray.
    const lid = this.studdedPanel(h * 0.84, h * 0.92);
    lid.position.set(w / 2 + h * 0.27, -h * 0.04);
    lid.rotation = 0.5;
    lid.scale.set(0.58, 0.96); // narrow → reads as an open lid seen at an angle
    lid.eventMode = 'static'; // click the lid to close Tooly
    lid.cursor = 'pointer';
    lid.on('pointerdown', () => this.toggleToolbox());
    box.addChild(lid);
    const hinges = new PIXI.Graphics();
    for (let k = -1; k <= 1; k++) {
      const hy = k * h * 0.26;
      hinges.beginFill(0x9aa1ab, 1);
      hinges.drawCircle(w / 2 + 3, hy, 7);
      hinges.endFill();
      hinges.beginFill(0x5b626c, 1);
      hinges.drawCircle(w / 2 + 3, hy, 3.2);
      hinges.endFill();
    }
    box.addChild(hinges);

    // Tray as a 3-D lego box: a dark front/side wall offset downward for depth,
    // a lighter top rim with studs around the border, and a recessed dark well.
    const tray = new PIXI.Graphics();
    tray.beginFill(0x000000, 0.28); // ground shadow
    tray.drawRoundedRect(-w / 2 + 8, -h / 2 + depth + 8, w, h, 12);
    tray.endFill();
    tray.beginFill(0x4e535a, 1); // front/side walls (the box's grey lego depth)
    tray.drawRoundedRect(-w / 2, -h / 2 + depth, w, h, 12);
    tray.endFill();
    tray.beginFill(0x8f949c, 1); // top rim (grey lego, lit)
    tray.drawRoundedRect(-w / 2, -h / 2, w, h, 12);
    tray.endFill();
    tray.beginFill(0xaab0b8, 1); // rim highlight (top edge)
    tray.drawRoundedRect(-w / 2 + 3, -h / 2 + 3, w - 6, 6, 4);
    tray.endFill();
    tray.beginFill(0x2f3338, 1); // recessed well (dark grey interior)
    tray.drawRoundedRect(-w / 2 + pad - 6, -h / 2 + pad - 6, w - 2 * (pad - 6), h - 2 * (pad - 6), 8);
    tray.endFill();
    box.addChild(tray);

    const left = -w / 2 + pad;
    const top = -h / 2 + pad;
    // Raised lego dividers between the compartments (so each tool sits in its
    // own recess, like the original).
    const div = new PIXI.Graphics();
    div.beginFill(0x6e727a, 1); // grey dividers
    for (let c = 1; c < cols; c++) {
      const x = left + c * cell + (c - 0.5) * gap;
      div.drawRoundedRect(x - gap / 2, -h / 2 + pad - 6, gap, h - 2 * (pad - 6), 3);
    }
    for (let r = 1; r < rows; r++) {
      const y = top + r * cell + (r - 0.5) * gap;
      div.drawRoundedRect(-w / 2 + pad - 6, y - gap / 2, w - 2 * (pad - 6), gap, 3);
    }
    div.endFill();
    box.addChild(div);

    // 2x4 grid of element stacks, in the source order (constant.h:1049 +
    // tools.cpp:4024): number, text / box, nest / scale, robot / truck, bomb.
    // (The wand, vacuum, pump and notebook are FLOOR items, not toolbox stacks.)
    // Each icon is rendered with renderThingDisplay, so it's the *real* element
    // art (green number plate, pink text plate, lego box, robot…) exactly as it
    // appears once pulled onto the floor.
    const picks = ['number', 'text', 'box', 'nest', 'scale', 'robot', 'truck', 'bomb'];
    picks.forEach((pick, i) => {
      const cx = left + (i % cols) * (cell + gap) + cell / 2;
      const cy = top + Math.floor(i / cols) * (cell + gap) + cell / 2;

      const slot = new PIXI.Graphics();
      slot.beginFill(0x26292e, 1); // recessed dark-grey compartment floor
      slot.drawRoundedRect(cx - cell / 2, cy - cell / 2, cell, cell, 5);
      slot.endFill();
      slot.lineStyle(1.5, 0x14161a, 0.5); // inner shadow at the top-left
      slot.moveTo(cx - cell / 2 + 2, cy + cell / 2 - 2);
      slot.lineTo(cx - cell / 2 + 2, cy - cell / 2 + 2);
      slot.lineTo(cx + cell / 2 - 2, cy - cell / 2 + 2);
      box.addChild(slot);

      const sample = this.sampleThing(pick);
      const iconNode = sample
        ? renderThingDisplay(sample, this.tools, this.theme, cell - 14, { static: true })
        : this.makeIcon(pick, cell - 12);
      iconNode.position.set(cx, cy);
      box.addChild(iconNode);

      const hit = new PIXI.Container();
      hit.position.set(cx, cy);
      hit.hitArea = new PIXI.Rectangle(-cell / 2, -cell / 2, cell, cell);
      hit.eventMode = 'static';
      hit.on('pointerdown', (e) => this.onPick(pick, e.global.x, e.global.y));
      box.addChild(hit);
    });
    return box;
  }

  /** A throwaway sample element for a toolbox slot, rendered with the real art. */
  private sampleThing(pick: string): Thing | null {
    switch (pick) {
      case 'number': return new NumberThing({ value: 1 });
      case 'text': return new TextThing({ value: 'A' });
      case 'box': return new Box({ size: 1 });
      case 'nest': return new Nest();
      case 'scale': return new Scale();
      case 'robot': return new Robot();
      case 'truck': return new Truck();
      case 'bomb': return new Bomb();
      default: return null;
    }
  }

  private makeIcon(key: string | undefined, size: number): PIXI.Container {
    const c = new PIXI.Container();
    const tex = key ? this.tools.get(key) : undefined;
    if (tex && tex !== PIXI.Texture.WHITE) {
      const s = new PIXI.Sprite(tex);
      s.anchor.set(0.5);
      const m = Math.max(s.width, s.height, 1);
      s.scale.set(size / m);
      c.addChild(s);
    }
    return c;
  }

  destroy(): void {
    this.floor.destroy();
    this.chrome.destroy({ children: true });
    this.cursor.destroy({ children: true });
  }
}
